import React, { useMemo, useState } from "react";

import {
  PieChart,
  Pie,
  Cell,
  Tooltip,
  Legend,
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid
} from "recharts";

function InsightsPage({
  transactions,
  alerts,
  insights,
  metrics,
  visuals,
  darkMode,
  goBack
})
 {


const [
showCoach,
setShowCoach
]=useState(false);

const [
reduction,
setReduction
]=useState(20);


  // AI CHATBOT STATE

const [chatMessages, setChatMessages] = useState([
  {
    sender: "bot",
    text: "Hi 👋 I am your Financial AI Assistant. Ask me anything about your spending."
  }
]);

const [userInput, setUserInput] = useState("");
    // ✅ Build chart data from transactions
const categoryTotals = {};

transactions.forEach((t) => {
  const cat = (t.category || "other").toLowerCase();
  const amount = Number(t.amount || 0);

  categoryTotals[cat] = (categoryTotals[cat] || 0) + amount;
});

// convert to recharts format
const data = Object.keys(categoryTotals).map((key) => ({
  name: key,
  value: categoryTotals[key]
}));

  const COLORS = ["#4f6df5", "#22c55e", "#f59e0b", "#ef4444", "#8b5cf6"];
  const [
savedActions,
setSavedActions
] = useState([]);

const [
coachMode,
setCoachMode
]
=
useState(
"balanced"
);

  // ✅ NEED vs WANT ANALYTICS
const needWantTotals = {
  Need: 0,
  Want: 0
};

transactions.forEach((txn) => {

  const type =
    txn.need_or_want ||
    txn.classify ||
    txn.need_want ||
    txn.need_vs_want ||
    "";

  const amount = Number(txn.amount || 0);

  if (type.toLowerCase() === "need") {
    needWantTotals.Need += amount;
  }

  if (type.toLowerCase() === "want") {
    needWantTotals.Want += amount;
  }
});

// PIE DATA
const needWantData = [
  {
    name: "Needs",
    value: needWantTotals.Need
  },
  {
    name: "Wants",
    value: needWantTotals.Want
  }
];

// TOTAL
const totalNeedWant =
  needWantTotals.Need + needWantTotals.Want;

// PERCENTAGES
const needPercent = totalNeedWant
  ? ((needWantTotals.Need / totalNeedWant) * 100).toFixed(1)
  : 0;

const wantPercent = totalNeedWant
  ? ((needWantTotals.Want / totalNeedWant) * 100).toFixed(1)
  : 0;

// DISCIPLINE SCORE
let disciplineScore = 100;

if (wantPercent > 60) {
  disciplineScore -= 40;
} else if (wantPercent > 40) {
  disciplineScore -= 25;
} else if (wantPercent > 25) {
  disciplineScore -= 10;
}

const exceededAlerts = alerts.filter(
  (a) => a.exceeded
).length;

disciplineScore -= exceededAlerts * 10;

if (disciplineScore < 0) {
  disciplineScore = 0;
}

// MONTHLY TREND
const monthlyTrendMap = {};

transactions.forEach((txn) => {

  if (!txn.date) return;

  const month = txn.date.slice(0, 7);

  const type =
    txn.need_or_want ||
    txn.classify ||
    txn.need_want ||
    txn.need_vs_want ||
    "";

  if (!monthlyTrendMap[month]) {
    monthlyTrendMap[month] = {
      month,
      Need: 0,
      Want: 0
    };
  }

  if (type.toLowerCase() === "need") {
    monthlyTrendMap[month].Need += Number(txn.amount || 0);
  }

  if (type.toLowerCase() === "want") {
    monthlyTrendMap[month].Want += Number(txn.amount || 0);
  }
});

const monthlyNeedWantData =
  Object.values(monthlyTrendMap);

// COLORS
const NEED_WANT_COLORS = [
  "#22c55e",
  "#ef4444"
];

  // 📊 Category Data
const categoryData =
Array.isArray(visuals?.expense_by_category)
? visuals.expense_by_category.map(item => ({
    name: item.category,
    value: item.amount
}))
: [];

  // 💰 Total Spend
  const totalSpend = useMemo(() => {
    return transactions.reduce((sum, t) => sum + Number(t.amount || 0), 0);
  }, [transactions]);

  // =======================
// EXTRA AI METRICS
// =======================

// small purchases
const smallTransactions =
transactions.filter(
(t)=>
Number(t.amount || 0) < 300
).length;


// category spending
const foodSpend =
categoryTotals["food"] || 0;

const shoppingSpend =
categoryTotals["shopping"] || 0;


// last week spend
let lastWeekSpend = 0;

transactions.forEach((t)=>{

if(!t.date) return;

const day =
new Date(t.date).getDate();

if(day>24){

lastWeekSpend +=
Number(
t.amount || 0
);

}

});

  // ✅ DAILY BURN RATE
const dailyBurnRate = transactions.length
  ? (totalSpend / 30).toFixed(0)
  : 0;

// ✅ SAVINGS POTENTIAL
const savingsPotential =
  wantPercent > 40
    ? Math.round((needWantTotals.Want * 0.3))
    : Math.round((needWantTotals.Want * 0.15));

// ✅ RISK LEVEL
let riskLevel = "Low";

if (wantPercent > 50 || exceededAlerts >= 2) {
  riskLevel = "High";
} else if (wantPercent > 30 || exceededAlerts >= 1) {
  riskLevel = "Medium";
}

// ✅ SPENDING STYLE
let spendingStyle = "Balanced";

if (wantPercent > 60) {
  spendingStyle = "Impulsive";
} else if (needPercent > 75) {
  spendingStyle = "Highly Disciplined";
} else if (wantPercent > 40) {
  spendingStyle = "Lifestyle Focused";
}

// ✅ FINANCIAL HEALTH
let financialHealth = "Excellent";

if (disciplineScore < 50) {
  financialHealth = "Critical";
} else if (disciplineScore < 70) {
  financialHealth = "Average";
} else if (disciplineScore < 85) {
  financialHealth = "Good";
}

  // 🔝 Top Category
  const topCategory = useMemo(() => {
    if (!categoryData.length) return null;
    return [...categoryData].sort((a, b) => b.value - a.value)[0];
  }, [categoryData]);

  // 🧠 AI Summary
  const aiSummary = useMemo(() => {
    if (!transactions.length) return "Upload a statement to see insights.";

    const alertMsg = alerts.find(a => a.exceeded)
      ? "Some of your budgets have been exceeded."
      : "You are mostly within your budget limits.";

    return `You spent a total of ₹${totalSpend.toFixed(0)} during this period. 
Your highest spending category was ${topCategory?.name}, indicating a key expense driver. 
${alertMsg} Your spending behavior suggests ${
      insights.length > 3 ? "diverse financial activity" : "disciplined spending"
    }.`;
  }, [transactions, alerts, insights, totalSpend, topCategory]);

// ==============================
// NEXT GEN FINTECH AI ENGINE
// ==============================

const recommendations = [];

function getCoachAdvice(rec){

let advice=[];

/* ===================
CATEGORY ANALYSIS
=================== */

if(topCategory){

advice.push(
`You currently spend most on ${topCategory.name}.`
);

if(
topCategory.value >
totalSpend*0.35
){

advice.push(
`${topCategory.name} contributes disproportionately to your budget.`
);

advice.push(
`Try reducing this category by 15–20%.`
);

}

}


/* ===================
WANTS ANALYSIS
=================== */

if(
wantPercent>50
){

advice.push(
`Your discretionary spending (${wantPercent}%) is unusually high.`
);

advice.push(
`Move at least ₹${Math.round(
needWantTotals.Want*0.20
)} toward savings.`
);

}

else if(
wantPercent>35
){

advice.push(
`Your wants are manageable but can improve.`
);

advice.push(
`Reduce impulse spending by ₹${Math.round(
needWantTotals.Want*0.10
)}.`
);

}

else{

advice.push(
`Your spending distribution looks healthy.`
);

}


/* ===================
SPENDING SPEED
=================== */

if(
projectedSpend>
totalSpend*1.2
){

advice.push(
`Your current pace may exceed monthly budget.`
);

advice.push(
`Reduce daily spend to approximately ₹${Math.round(
dailyBurnRate*0.80
)}.`
);

}


/* ===================
WEEKEND ANALYSIS
=================== */

if(
weekendSpend>
totalSpend*0.30
){

advice.push(
`Weekend spending contributes heavily.`
);

advice.push(
`Set weekend budget cap of ₹${Math.round(
weekendSpend*0.70
)}.`
);

}


/* ===================
MICRO LEAKS
=================== */

if(
smallTransactions>15
){

advice.push(
`${smallTransactions} small purchases detected.`
);

advice.push(
`Bundle subscriptions and reduce low-value spending.`
);

}


/* ===================
RECOVERY PLAN
=================== */

let recover = [];

recover.push(
`Essentials: ${Math.max(
70,
needPercent
)}%`
);

recover.push(
`Lifestyle: ${Math.min(
30,
wantPercent
)}%`
);

recover.push(
`Savings: 20%`
);


/* ===================
FINAL MESSAGE
=================== */

return `

📊 Spending Diagnosis

${advice.join("\n\n")}

━━━━━━━━━━━━━━

💰 Budget Recovery Plan

${recover.join("\n")}

━━━━━━━━━━━━━━

📈 Predicted Savings

₹${savingsPotential}

━━━━━━━━━━━━━━

🎯 Coach Goal

Increase discipline score from
${disciplineScore}
→
${Math.min(
100,
disciplineScore+12
)}

Expected recovery:
14–30 days

`;

}

const achievements = [];

/* ==========================
REAL TIME FINTECH SIGNALS
========================== */

// Current day
const today = new Date().getDate();

// Projected monthly spending
const projectedSpend =
today
? Math.round(
(totalSpend / today) * 30
)
: totalSpend;


// Recent 7 day spend
let recentSpend = 0;

transactions.forEach((t) => {

if (!t.date) return;

const txnDate =
new Date(t.date);

const diff =
(Date.now() -
txnDate.getTime())
/
(1000*60*60*24);

if(diff<=7){

recentSpend +=
Number(t.amount||0);

}

});


// High value transaction detector
const highSpendCount =
transactions.filter(

t=>
Number(t.amount)>3000

).length;


// Weekend spending
let weekendSpend = 0;

transactions.forEach((t)=>{

if(!t.date)return;

const day =
new Date(
t.date
).getDay();

if(
day===0||
day===6
){

weekendSpend+=
Number(
t.amount||0
);

}

});


// Category frequency
const categoryFrequency = {};

transactions.forEach((t)=>{

const c =
(
t.category||
"Other"
);

categoryFrequency[c]=
(
categoryFrequency[c]||0
)+1;

});

const topFreqCategory =
Object.entries(
categoryFrequency
)

.sort(
(a,b)=>
b[1]-a[1]
)

[0]?.[0];

const totalTx = transactions.length;

const avgTxn =
totalTx
? totalSpend / totalTx
: 0;

const spendVelocity =
(
totalSpend /
Math.max(
new Set(
transactions.map(
(t)=>t.date?.slice(0,10)
)
).size,
1
)
).toFixed(0);

const savingRate =
(
(
needWantTotals.Need /
Math.max(totalSpend,1)
)*100
).toFixed(0);

const scoreColor =
disciplineScore>=85
? "excellent"
: disciplineScore>=70
? "good"
: disciplineScore>=50
? "warning"
: "danger";

const recoveredSavings =
Math.round(
savingsPotential *
(reduction/100)
);

const recoveredDailySpend =
Math.max(
0,
dailyBurnRate -
(recoveredSavings/30)
).toFixed(0);

const coachStrategies = {

aggressive:[
"Cut wants by 30%",
"Move ₹300/day to savings",
"Freeze shopping for 7 days",
"Weekend spend limit ₹500"
],

balanced:[
"Reduce wants by 15%",
"Track subscriptions",
"Save ₹150/day",
"Weekly budget check"
],

comfort:[
"Reduce wants by 8%",
"Keep lifestyle spending",
"Save gradually",
"Limit impulse buying"
]

};

const projectedScore =
Math.min(
100,
disciplineScore +
Math.round(reduction/5)
);

// ======================
// BUDGET SIMULATOR
// ======================

const simulatedSavings =
Math.round(
needWantTotals.Want
*
(reduction/100)
);

const projectedDiscipline =
Math.min(
100,
disciplineScore +
Math.round(
reduction/5
)
);

const newMonthlySpend =
Math.round(
totalSpend -
simulatedSavings
);

const dailyLimit =
Math.round(
newMonthlySpend / 30
);

const recoveryDays =
Math.max(
7,
Math.round(
30 -
(reduction*0.4)
)
);



// AI Recommendation Helper

function addRec(
priority,
title,
description,
action,
impact
){

recommendations.push({
priority,
title,
description,
action,
impact
});

}



// ========= RISK =========

if(wantPercent>55){

addRec(

100,

"High Lifestyle Inflation",

`Your discretionary expenses reached ${wantPercent}% of total spending.`,

"Reduce entertainment/shopping budget by 20%",

`Save ₹${Math.round(
needWantTotals.Want*0.20
)}`

);

}



// ========= MICRO =========

if(smallTransactions>12){

addRec(

85,

"Subscription & Small Leak Detection",

`${smallTransactions} low-value purchases detected.`,

"Bundle recurring purchases",

"Reduce 8–12% monthly leakage"

);

}



// ========= FOOD =========

if(foodSpend>3000){

addRec(

90,

"Food Optimization Opportunity",

`Food spending is ₹${foodSpend}.`,

"Use weekly meal planning",

`Save ₹${Math.round(
foodSpend*0.18
)}`

);

}



// ========= MONTH END =========

if(lastWeekSpend>
totalSpend*0.35){

addRec(

95,

"Month-End Cash Burn",

"Expenses accelerate near month-end.",

"Introduce weekly caps",

"Improve cash stability"

);

}



// ========= DISCIPLINE =========

if(
disciplineScore>85
){

achievements.push(
"🏆 Elite Financial Discipline"
);

}

if(
savingRate>70
){

achievements.push(
"💎 Long-Term Saver"
);

}

if(
wantPercent<30
){

achievements.push(
"🔥 Spending Optimizer"
);

}



// SORT
recommendations.sort(
(a,b)=>
b.priority-a.priority
);

/* ==========================
REAL TIME FINTECH ENGINE
========================== */


// Forecast Overspend
if(
projectedSpend>
totalSpend*1.2
){

recommendations.push({

type:"warning",

title:
"Projected Monthly Overspend",

description:
`Current pace suggests ₹${projectedSpend} spending this month.`,

impact:
`Reduce daily spend by ₹${Math.round(
(projectedSpend-totalSpend)/10
)}`,

confidence:"96%",

priority:100

});

}


// Spending acceleration
if(
recentSpend>
totalSpend*0.45
){

recommendations.push({

type:"warning",

title:
"Spending Acceleration",

description:
"Your recent spending velocity increased unusually.",

impact:
"Pause discretionary spending for 3 days",

confidence:"94%",

priority:95

});

}


// High transaction detector
if(
highSpendCount>=3
){

recommendations.push({

type:"insight",

title:
"High Ticket Purchases",

description:
`${highSpendCount} large transactions detected.`,

impact:
"Review one-time expenses",

confidence:"91%",

priority:85

});

}


// Weekend leakage
if(
weekendSpend>
totalSpend*0.35
){

recommendations.push({

type:"habit",

title:
"Weekend Overspending",

description:
"Weekend expenses contribute heavily.",

impact:
"Set a weekend spending cap",

confidence:"90%",

priority:80

});

}


// Category concentration
if(
topFreqCategory
){

recommendations.push({

type:"success",

title:
"Dominant Spending Pattern",

description:
`Most spending happens in ${topFreqCategory}.`,

impact:
"Create category-based budgeting",

confidence:"89%",

priority:50

});

}

recommendations.sort(
(a,b)=>
(b.priority||0)
-
(a.priority||0)
);
// ======================================
// ACHIEVEMENTS
// ======================================

if (disciplineScore >= 85) {
  achievements.push(
    "🏆 Financial Discipline Master"
  );
}

if (needPercent >= 75) {
  achievements.push(
    "🔥 Smart Budgeting Expert"
  );
}

if (wantPercent < 30) { 
  achievements.push(
    "💎 Controlled Lifestyle Spender"
  );
}

const handleSendMessage = () => {

  if (!userInput.trim()) return;

  const userMessage = {
    sender: "user",
    text: userInput
  };

  let botReply =
    "I couldn't understand that. Try asking about spending, savings or budget.";

  const question = userInput.toLowerCase();

  if (
    question.includes("spend") ||
    question.includes("spent")
  ) {
    botReply =
      `You spent ₹${totalSpend.toFixed(0)} in total.`;
  }

  else if (
    question.includes("saving")
  ) {
    botReply =
      `Your estimated savings potential is ₹${savingsPotential}.`;
  }

  else if (
    question.includes("discipline")
  ) {
    botReply =
      `Your financial discipline score is ${disciplineScore}/100.`;
  }

  else if (
    question.includes("risk")
  ) {
    botReply =
      `Your current overspending risk level is ${riskLevel}.`;
  }

  else if (
    question.includes("top category")
  ) {
    botReply =
      `Your highest spending category is ${topCategory?.name}.`;
  }

  else if (
    question.includes("want")
  ) {
    botReply =
      `You spend ${wantPercent}% on discretionary purchases.`;
  }

  const botMessage = {
    sender: "bot",
    text: botReply
  };

  setChatMessages(prev => [
    ...prev,
    userMessage,
    botMessage
  ]);

  setUserInput("");
};

  return (
    <div className="container" style={{ marginTop: "20px" }}>

      {/* HEADER */}
      <div className="card" style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <div>
          <h2>AI Financial Insights</h2>
          <p style={{ fontSize: "13px", color: "#6b7280" }}>
            Smart analysis of your spending behavior
          </p>
        </div>

        <button
          onClick={goBack}
          style={{
            padding: "6px 14px",
            borderRadius: "8px",
            border: "none",
            background: "#4f6df5",
            color: "#fff",
            cursor: "pointer"
          }}
        >
          ← Back
        </button>
      </div>
</div>
  )
      
   {/* KPI CARDS */}
<div
  style={{
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(250px, 1fr))",
    columnGap: "20px",
    rowGap: "32px",
    marginTop: "20px",
    alignItems: "stretch"
  }}
>

  {/* TOTAL SPEND */}
  <div className="card">
    <h4>Total Spend</h4>

    <p style={{ fontSize: "20px", fontWeight: "600" }}>
      ₹{totalSpend.toFixed(0)}
    </p>
  </div>

  {/* TOP CATEGORY */}
  <div className="card">
    <h4>Top Category</h4>

    <p style={{ fontSize: "18px", fontWeight: "600" }}>
      {topCategory?.name || "-"}
    </p>
  </div>

  {/* TRANSACTIONS */}
  <div className="card">
    <h4>Transactions</h4>

    <p style={{ fontSize: "18px", fontWeight: "600" }}>
      {transactions.length}
    </p>
  </div>

  {/* DISCIPLINE SCORE */}
  <div className="card">
    <h4>Discipline Score</h4>

    <p style={{
      fontSize: "20px",
      fontWeight: "600"
    }}>
      {disciplineScore}/100
    </p>

    <small>
      Needs {needPercent}% | Wants {wantPercent}%
    </small>
  </div>

</div>

{/* SMART FINANCIAL HEALTH */}
<div
  style={{
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit,minmax(220px,1fr))",
    gap: "20px",
    marginTop: "20px"
  }}
>

  {/* HEALTH STATUS */}
  <div
    style={{
      background: darkMode ? "#111827" : "#ffffff",
      padding: "22px",
      borderRadius: "18px",
      boxShadow: darkMode
        ? "0 4px 20px rgba(0,0,0,0.4)"
        : "0 4px 20px rgba(0,0,0,0.08)"
    }}
  >
    <h4 style={{ marginBottom: "10px" }}>
      Financial Health
    </h4>

    <div
      style={{
        fontSize: "22px",
        fontWeight: "700",
        color:
          financialHealth === "Excellent"
            ? "#22c55e"
            : financialHealth === "Good"
            ? "#4f6df5"
            : financialHealth === "Average"
            ? "#f59e0b"
            : "#ef4444"
      }}
    >
      {financialHealth}
    </div>

    <small>
      Based on spending discipline
    </small>
  </div>

  {/* SAVINGS POTENTIAL */}
  <div
    style={{
      background: darkMode ? "#111827" : "#ffffff",
      padding: "22px",
      borderRadius: "18px",
      boxShadow: darkMode
        ? "0 4px 20px rgba(0,0,0,0.4)"
        : "0 4px 20px rgba(0,0,0,0.08)"
    }}
  >
    <h4 style={{ marginBottom: "10px" }}>
      Savings Potential
    </h4>

    <div
      style={{
        fontSize: "24px",
        fontWeight: "700",
        color: "#22c55e"
      }}
    >
      ₹{savingsPotential}
    </div>

    <small>
      Estimated reducible spending
    </small>
  </div>

  {/* RISK LEVEL */}
  <div
    style={{
      background: darkMode ? "#111827" : "#ffffff",
      padding: "22px",
      borderRadius: "18px",
      boxShadow: darkMode
        ? "0 4px 20px rgba(0,0,0,0.4)"
        : "0 4px 20px rgba(0,0,0,0.08)"
    }}
  >
    <h4 style={{ marginBottom: "10px" }}>
      Overspending Risk
    </h4>

    <div
      style={{
        fontSize: "22px",
        fontWeight: "700",
        color:
          riskLevel === "Low"
            ? "#22c55e"
            : riskLevel === "Medium"
            ? "#f59e0b"
            : "#ef4444"
      }}
    >
      {riskLevel}
    </div>

    <small>
      Based on alerts & wants ratio
    </small>
  </div>

  {/* SPENDING STYLE */}
  <div
    style={{
