{/* AI CHATBOT */}

<div
  style={{
    marginTop: "25px",
    background: darkMode ? "#111827" : "#ffffff",
    borderRadius: "20px",
    padding: "24px",
    boxShadow: darkMode
      ? "0 4px 20px rgba(0,0,0,0.4)"
      : "0 4px 20px rgba(0,0,0,0.08)"
  }}
>
  <h3>🤖 Financial AI Chatbot</h3>

  <div
    style={{
      height: "300px",
      overflowY: "auto",
      marginTop: "15px",
      padding: "10px",
      borderRadius: "12px",
      background: darkMode
        ? "#0f172a"
        : "#f9fafb"
    }}
  >
    {chatMessages.map((msg, index) => (

      <div
        key={index}
        style={{
          textAlign:
            msg.sender === "user"
              ? "right"
              : "left",

          marginBottom: "10px"
        }}
      >
        <span
          style={{
            display: "inline-block",
            padding: "10px 14px",
            borderRadius: "12px",

            background:
              msg.sender === "user"
                ? "#4f6df5"
                : darkMode
                ? "#1e293b"
                : "#e5e7eb",

            color:
              msg.sender === "user"
                ? "#fff"
                : darkMode
                ? "#fff"
                : "#111"
          }}
        >
          {msg.text}
        </span>
      </div>

    ))}
  </div>

  <div
    style={{
      display: "flex",
      gap: "10px",
      marginTop: "15px"
    }}
  >
    <input
      value={userInput}
      onChange={(e) =>
        setUserInput(e.target.value)
      }
      placeholder="Ask about spending, savings, risk..."
      style={{
        flex: 1,
        padding: "12px",
        borderRadius: "10px",
        border: "1px solid #d1d5db"
      }}
    />

    <button
      onClick={handleSendMessage}
      style={{
        background: "#4f6df5",
        color: "#fff",
        border: "none",
        padding: "12px 20px",
        borderRadius: "10px",
        cursor: "pointer"
      }}
    >
      Send
    </button>
  </div>
</div>

